/* @catalog — generated by `npm run catalog:generate`; do not edit by hand.
 * Internal
 *   Classes: UploadRequest
 *   Functions: options, started
 *   Constants: viewer, responseSchema, uploads
 * Tests
 *   - measured upload progress reaches 100 percent while the server receipt remains outstanding
 *   - missing browser totals remain indeterminate and invalid progress measurements are ignored
 *   - upload responses retain HTTP errors and bounded Retry-After rather than bypassing shared response handling
 *   - an upload with a no-content receipt shares the same measured transport and status contract
 *   - upload responses require the same private viewer echo and strict JSON schema
 *   - abort stops upload events and network failure retains the shared uncertain transport error
 *   - account changes fence late upload progress before it reaches private presentation
 *   - authentication refresh replays the exact Blob and operation once and resets measured progress
 *   - upload transport cannot send an off-origin URL or an already-aborted body
 *   - cancelling while a transport response decodes prevents a late successful result
 * @end-catalog */

import { z } from 'zod';
import { advanceAccountEpoch } from './accountEpoch';
import { apiRequest, apiRequestNoContent, type ApiResponseTransport, type UploadProgress } from './client';
import { uploadResponse } from './uploadResponse';

const viewer = 'upload-viewer';
const responseSchema = z.object({ ready: z.boolean() }).strict();
const uploads: UploadRequest[] = [];

/** Models upload and response events independently so completed bytes never imply an acknowledged mutation. */
class UploadRequest {
  upload = { onprogress: null as ((event: ProgressEvent) => void) | null, onload: null as (() => void) | null };
  onload: (() => void) | null = null;
  onerror: (() => void) | null = null;
  onabort: (() => void) | null = null;
  ontimeout: (() => void) | null = null;
  responseType = ''; status = 0; statusText = ''; responseText = '';
  headers = new Headers(); responseHeaders = new Headers();
  method = ''; path = ''; body: Blob | null = null; aborted = false;
  constructor() { uploads.push(this); }
  open(method: string, path: string) { this.method = method; this.path = path; }
  setRequestHeader(name: string, value: string) { this.headers.set(name, value); }
  send(body: Blob) { this.body = body; }
  abort() { this.aborted = true; this.onabort?.(); }
  getAllResponseHeaders() { return [...this.responseHeaders].map(([name, value]) => `${name}: ${value}`).join('\r\n'); }
  progress(loaded: number, total = 0, lengthComputable = true) {
    this.upload.onprogress?.({ loaded, total, lengthComputable } as ProgressEvent);
  }
  respond(body: unknown = { ready: true }, status = 200, account: string | null = viewer, headers: Record<string, string> = {}) {
    this.status = status; this.responseText = JSON.stringify(body);
    this.responseHeaders = new Headers({ 'Content-Type': 'application/json', ...headers });
    if (account) this.responseHeaders.set('X-Finitude-Account-Viewer', account);
    this.onload?.();
  }
}

beforeEach(() => { uploads.length = 0; vi.stubGlobal('XMLHttpRequest', UploadRequest); });
const options = (onUploadProgress: (progress: UploadProgress) => void, body = new Blob(['0123456789'])) => ({
  method: 'POST', body, accountViewer: viewer, cache: 'no-store' as const,
  responseTransport: ((path, init, headers, assertCurrent) => uploadResponse(path, init, headers, onUploadProgress, assertCurrent)) satisfies ApiResponseTransport,
  headers: { 'Content-Type': 'multipart/form-data; boundary=original', 'Idempotency-Key': 'original-operation', 'If-Match': '7' }
});
/** Waits for the caller-supplied transport without depending on its startup timing. */
const started = (count = 1) => vi.waitFor(() => { expect(uploads).toHaveLength(count); return uploads[count - 1]; });

test('measured upload progress reaches 100 percent while the server receipt remains outstanding', async () => {
  const progress = vi.fn(), body = new Blob(['0123456789']);
  const request = apiRequest('/api/admin/v1/video-projects/project/source', responseSchema, options(progress, body));
  const xhr = await started();
  expect(xhr.path).toBe('/api/admin/v1/video-projects/project/source'); expect(xhr.method).toBe('POST');
  expect(xhr.body).toBe(body); expect(xhr.headers.get('Accept')).toBe('application/json');
  expect(xhr.headers.get('Content-Type')).toBe('multipart/form-data; boundary=original');
  expect(xhr.headers.get('X-Finitude-Account-Viewer')).toBe(viewer);
  expect(xhr.headers.get('Cache-Control')).toBe('no-cache'); expect(xhr.headers.get('Pragma')).toBe('no-cache');
  xhr.progress(5, 10); xhr.upload.onload?.();
  expect(progress.mock.calls.map(([event]) => event)).toEqual([{ loaded: 0, total: 10 }, { loaded: 5, total: 10 }, { loaded: 10, total: 10 }]);
  let acknowledged = false; void request.then(() => { acknowledged = true; });
  await Promise.resolve(); expect(acknowledged).toBe(false);
  xhr.respond(); await expect(request).resolves.toEqual({ ready: true });
  expect(xhr.upload.onprogress).toBeNull();
});

test('missing browser totals remain indeterminate and invalid progress measurements are ignored', async () => {
  const progress = vi.fn(), request = apiRequest('/upload', responseSchema, options(progress));
  const xhr = await started();
  xhr.progress(3, 10, false); xhr.progress(4, 0); xhr.progress(Infinity, 10); xhr.progress(-1, 10);
  xhr.progress(15, 10);
  expect(progress.mock.calls.map(([event]) => event)).toEqual([{ loaded: 0, total: 10 }, { loaded: 3, total: null }, { loaded: 4, total: null }, { loaded: 10, total: 10 }]);
  xhr.respond(); await request;
});

test('upload responses retain HTTP errors and bounded Retry-After rather than bypassing shared response handling', async () => {
  const request = apiRequest('/upload', responseSchema, options(vi.fn()));
  (await started()).respond({ code: 'capacity' }, 429, viewer, { 'Retry-After': '600' });
  await expect(request).rejects.toMatchObject({ kind: 'http', status: 429, code: 'capacity', retryAfterSeconds: 60 });
});

test('an upload with a no-content receipt shares the same measured transport and status contract', async () => {
  const progress = vi.fn(), request = apiRequestNoContent('/upload', options(progress));
  const xhr = await started(); xhr.upload.onload?.(); xhr.respond(null, 204);
  await expect(request).resolves.toBeUndefined();
  expect(progress.mock.calls.map(([event]) => event)).toEqual([{ loaded: 0, total: 10 }, { loaded: 10, total: 10 }]);
});

test('upload responses require the same private viewer echo and strict JSON schema', async () => {
  const mismatch = apiRequest('/upload', responseSchema, options(vi.fn()));
  (await started()).respond({ ready: true }, 200, 'another-viewer');
  await expect(mismatch).rejects.toMatchObject({ kind: 'invalid-response', code: 'account_viewer_mismatch' });
  const invalid = apiRequest('/upload', responseSchema, options(vi.fn()));
  (await started(2)).respond({ ready: true, privateValue: 'unexpected' });
  await expect(invalid).rejects.toMatchObject({ kind: 'invalid-response', status: 200 });
});

test('abort stops upload events and network failure retains the shared uncertain transport error', async () => {
  const controller = new AbortController(), progress = vi.fn();
  const request = apiRequest('/upload', responseSchema, { ...options(progress), signal: controller.signal });
  const late = (await started()).upload.onprogress!;
  controller.abort(); late({ loaded: 5, total: 10, lengthComputable: true } as ProgressEvent);
  await expect(request).rejects.toMatchObject({ name: 'AbortError' });
  expect(uploads[0].aborted).toBe(true); expect(progress).toHaveBeenCalledTimes(1);
  const failed = apiRequest('/upload', responseSchema, options(vi.fn())); (await started(2)).onerror?.();
  await expect(failed).rejects.toMatchObject({ kind: 'network' });
});

test('account changes fence late upload progress before it reaches private presentation', async () => {
  const progress = vi.fn(), request = apiRequest('/upload', responseSchema, options(progress));
  const xhr = await started(); advanceAccountEpoch(); xhr.progress(5, 10);
  await expect(request).rejects.toMatchObject({ kind: 'invalid-response', code: 'account_viewer_mismatch' });
  expect(progress).toHaveBeenCalledTimes(1); expect(uploads[0].aborted).toBe(true);
});

test('authentication refresh replays the exact Blob and operation once and resets measured progress', async () => {
  const session = { user: { id: viewer, email: 'upload@example.com', role: 'admin', displayName: 'Upload', avatarRevision: 0, avatar: null, emailVerified: true } };
  const fetcher = vi.fn(async (path: string) => new Response(JSON.stringify(path === '/auth/browser/refresh' ? session : {}), {
    status: path === '/auth/browser/refresh' ? 200 : 401,
    headers: { 'Content-Type': 'application/json', 'X-Finitude-Account-Viewer': viewer }
  }));
  vi.stubGlobal('fetch', fetcher);
  const progress = vi.fn(), body = new Blob(['0123456789']), request = apiRequest('/upload', responseSchema, options(progress, body));
  const late = (await started()).upload.onprogress!;
  uploads[0].progress(5, 10); uploads[0].respond({}, 401);
  await vi.waitFor(() => expect(uploads).toHaveLength(2));
  expect(uploads[1].body).toBe(body); expect([...uploads[1].headers]).toEqual([...uploads[0].headers]);
  expect(fetcher.mock.calls.map(([path]) => path)).toEqual(['/auth/browser/session', '/auth/browser/refresh']);
  expect(progress.mock.calls.map(([event]) => event.loaded)).toEqual([0, 5, 0]);
  late({ loaded: 10, total: 10, lengthComputable: true } as ProgressEvent);
  expect(progress).toHaveBeenCalledTimes(3);
  uploads[1].respond(); await expect(request).resolves.toEqual({ ready: true });
});

test('upload transport cannot send an off-origin URL or an already-aborted body', async () => {
  await expect(apiRequest('https://example.com/upload', responseSchema, options(vi.fn()))).rejects.toMatchObject({ kind: 'network' });
  const controller = new AbortController(); controller.abort();
  await expect(apiRequest('/upload', responseSchema, { ...options(vi.fn()), signal: controller.signal })).rejects.toMatchObject({ name: 'AbortError' });
  expect(uploads).toHaveLength(0);
});

test('cancelling while a transport response decodes prevents a late successful result', async () => {
  const controller = new AbortController();
  let finish!: (body: unknown) => void;
  const response = new Response(null, { headers: { 'X-Finitude-Account-Viewer': viewer } });
  const decode = vi.spyOn(response, 'json').mockImplementation(() => new Promise(resolve => { finish = resolve; }));
  const request = apiRequest('/upload', responseSchema, {
    ...options(vi.fn()), signal: controller.signal, responseTransport: async () => response
  });
  await vi.waitFor(() => expect(decode).toHaveBeenCalledOnce());
  controller.abort(); finish({ ready: true });
  await expect(request).rejects.toMatchObject({ name: 'AbortError' });
});
